/* @lc app=leetcode id=1286 lang=kotlin */ class CombinationIterator(characters: String, combinationLength: Int, val l: List<String> = (1 until (1 shl characters.length)).filter { Integer.bitCount(it) == combinationLength }.map { m -> characters.indices.filter { m shr it and 1 == 1 }.map { characters[it] }.joinToString("") }.sorted(), val i: IntArray = IntArray(1)) { fun next(): String = l[i[0]++] fun hasNext(): Boolean = i[0] < l.size }